# The `tag` Function

```js
/** @param {Parser} parser */
export default function tag(parser) {
	const start = parser.index;
	parser.index += 1;

	parser.allow_whitespace();

	if (parser.eat('#')) return open(parser);
	if (parser.eat(':')) return next(parser);
	if (parser.eat('@')) return special(parser);
	if (parser.match('/')) {
		if (!parser.match('/*') && !parser.match('//')) {
			parser.eat('/');
			return close(parser);
		}
	}

	const declaration = read_declaration(parser);
	if (declaration) {
		parser.append({
			type: 'DeclarationTag',
			start,
			end: parser.index,
			declaration: /** @type {VariableDeclaration} */ (declaration),
			metadata: {
				expression: new ExpressionMetadata()
			}
		});
		return;
	}

	const expression = read_expression(parser);

	parser.allow_whitespace();
	parser.eat('}', true);

	parser.append({
		type: 'ExpressionTag',
		start,
		end: parser.index,
		expression,
		metadata: {
			expression: new ExpressionMetadata()
		}
	});
}
```

# The `read_declaration` Function

```js
function read_declaration(parser) {
	const start = parser.index;

	const unsupported = parser.match_regex(regex_unsupported_declaration);
	if (unsupported) {
		e.declaration_tag_invalid_type({ start, end: start + unsupported.length });
	}

	if (
		!parser.match_regex(regex_supported_declaration) &&
		!parser.match_regex(regex_maybe_type_declaration)
	) {
		return null;
	}

	const initial_comment_count = parser.root.comments.length;

	let declaration;
	try {
		declaration = parse_statement_at(parser, parser.template, start);
	} catch (error) {
		if (!parser.loose) throw error;

		const end = find_matching_bracket(parser.template, start, '{');
		if (end === undefined) throw error;

		parser.index = end;
		const kind = parser.template.startsWith('const', start) ? 'const' : 'let';

		declaration = {
			type: 'VariableDeclaration',
			kind,
			declarations: [
				{
					type: 'VariableDeclarator',
					id: {
						type: 'Identifier',
						name: '',
						start: parser.index,
						end: parser.index
					},
					init: null,
					start: parser.index,
					end: parser.index
				}
			],
			start,
			end
		};
	}

	if (declaration.type !== 'VariableDeclaration') {
		if (declaration.type === 'ExpressionStatement') {
			parser.root.comments.length = initial_comment_count; // Else they show up duplicated
			return null;
		} else {
			// This is a TSTypeAliasDeclaration
			e.declaration_tag_invalid_type({
				start: declaration.start ?? start,
				end: declaration.end ?? parser.index
			});
		}
	}

	// TODO support using
	if (declaration.kind !== 'let' && declaration.kind !== 'const') {
		e.declaration_tag_invalid_type(declaration);
	}

	parser.index = /** @type {number} */ (declaration.end);
	parser.allow_whitespace();
	parser.eat('}', true);

	return declaration;
}
```

# Notes on Behavior

**Handling of the `type` identifier:** Since `type` isn't reserved and can appear in valid expressions, the code deliberately does not treat it as a declaration up front. Instead it matches the shape via `regex_maybe_type_declaration`, then parses the statement. If parsing yields an `ExpressionStatement` (e.g. `type` used as a plain identifier), it restores the comment count and returns `null` so it can be reprocessed as an expression. If it yields a `TSTypeAliasDeclaration`, that's rejected.

**Division operator in loose mode:** In the `tag` function, `parser.match('/')` only proceeds to `close(parser)` when it is *not* followed by `/*` or `//` (comments). In `read_declaration`, when `parse_statement_at` throws and loose mode is active, it attempts `find_matching_bracket` to locate the end and builds a placeholder empty-named declaration rather than failing.

**Where `declaration_tag_invalid_type` is emitted:** Three places in `read_declaration`:
1. When an unsupported keyword (`var`, `interface`, `enum`) is matched.
2. When the parsed node is neither a `VariableDeclaration` nor `ExpressionStatement` (the type-alias branch).
3. When the declaration kind is neither `let` nor `const` (the `// TODO support using` check).

