export function find_matching_bracket(template, index, open) {
	const close = default_brackets[open];
	let brackets = 1;
	let i = index;
	while (brackets > 0 && i < template.length) {
		const char = template[i];
		switch (char) {
			case "'":
			case '"':
			case '`':
				i = find_string_end(template, i + 1, char) + 1;
				continue;
			case '/': {
				const next_char = template[i + 1];
				if (!next_char) {
					// `/` is the last character; advance past it so we don't loop forever
					i++;
					continue;
				}
				if (next_char === '/') {
					i = infinity_if_negative(template.indexOf('
', i + 1)) + '
'.length;
					continue;
				}
				if (next_char === '*') {
					i = infinity_if_negative(template.indexOf('*/', i + 1)) + '*/'.length;
					continue;
				}
				const end = find_regex_end(template, i + 1) + '/'.length;
				if (end === Infinity) {
					i++;
				} else {
					i = end;
				}
				continue;
			}
			default: {
				const char = template[i];
				if (char === open) {
					brackets++;
				} else if (char === close) {
					brackets--;
				}
				if (brackets === 0) {
					return i;
				}
				i++;
			}
		}
	}
	return undefined;
}
```

**Handling of the `/` case:**

The code examines the character immediately following the slash to decide how to proceed:

1. **End of input:** If there is no next character, it simply advances `i++`. The comment explains it advances past the slash "so we don't loop forever."

2. **Line comment (`//`):** When `next_char === '/'`, it jumps to just after the next newline using `indexOf('
', ...)`, guarded by `infinity_if_negative`, plus the newline length.

3. **Block comment (`/*`):** When `next_char === '*'`, it jumps to just after the closing `*/` using `indexOf('*/', ...)`, again wrapped in `infinity_if_negative`, plus the length of `*/`.

4. **Regex (fallthrough):** Otherwise it calls `find_regex_end` and adds the slash length. If the result is `Infinity` (not found), it only advances `i++`; otherwise it jumps to `end`.

Note that this function doesn't explicitly distinguish division from regex—any non-comment slash is treated as a potential regex start, and if `find_regex_end` fails to locate a valid terminator it falls back to advancing a single character.

